class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: Raw SQL queries using "Discriminator" still work because
        // we preserved the property name via HasDiscriminator("Discriminator") above.
        // No change needed for: SELECT * FROM c WHERE c.Discriminator = 'Blog'

        // Breaking change 5: In .NET 9, Sync I/O on Cosmos DB throws by default.
        // Use async methods or opt-in to sync via CosmosOptionsExtension.
        // Fix: convert to async.
        var blogs = context.Blogs.ToListAsync().GetAwaiter().GetResult();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChangesAsync().GetAwaiter().GetResult();
    }
}

